#include <bits/stdc++.h>
using namespace std;

int largestRectangleArea(vector<int>& heights) {
    int n = heights.size();
    stack<int> st;
    int ans = 0;
    for (int i = 0; i <= n; ++i) {
        int cur = i == n ? 0 : heights[i];  // sentinel height 0
        while (!st.empty() && heights[st.top()] > cur) {
            int h = heights[st.top()];
            st.pop();
            int left = st.empty() ? -1 : st.top();
            ans = max(ans, h * (i - left - 1));
        }
        st.push(i);
    }
    return ans;
}

